function validate([n, k, budget, composition, stock, cost]) {
  if (!Number.isInteger(n) || n < 1 || n > 100) return 'n is between 1 and 100.';
  if (!Number.isInteger(k) || k < 1 || k > 100) return 'k is between 1 and 100.';
  if (!Number.isInteger(budget) || budget < 0 || budget > 1e8) return 'budget is between 0 and 10^8.';
  if (!Array.isArray(composition) || composition.length !== k) return 'composition needs exactly k rows.';
  for (const row of composition) {
    if (!Array.isArray(row) || row.length !== n) return 'Each composition row needs exactly n values.';
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each composition value is between 1 and 100.';
  }
  if (!Array.isArray(stock) || stock.length !== n) return 'stock needs exactly n values.';
  if (!Array.isArray(cost) || cost.length !== n) return 'cost needs exactly n values.';
  if (stock.some(v => !Number.isInteger(v) || v < 0 || v > 1e8)) return 'Each stock value is between 0 and 10^8.';
  if (cost.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each cost is between 1 and 100.';
  return null;
}

