function maxNumberOfAlloys(n, k, budget, composition, stock, cost) {
  const canMake = (machine, count) => {
    let spent = 0;
    for (let j = 0; j < n; j++) {
      const missing = machine[j] * count - stock[j];
      if (missing > 0) {
        spent += missing * cost[j];
      }
      if (spent > budget) {
        return false;
      }
    }
    return true;
  };
  let best = 0;
  for (const machine of composition) {
    let low = 0;
    let high = Math.min(...stock) + budget;
    while (low < high) {
      const mid = Math.floor((low + high + 1) / 2);
      if (canMake(machine, mid)) {
        low = mid;
      } else {
        high = mid - 1;
      }
    }
    best = Math.max(best, low);
  }
  return best;
}

