function maxNumberOfAlloys(n, k, budget, composition, stock, cost) {
  const price = (row, count) => row.reduce((total, need, j) => total + Math.max(0, need * count - stock[j]) * cost[j], 0);
  let answer = 0;
  for (let i = 0; i < k; i++) {
    // Build the largest affordable count one decimal digit at a time, from the top digit down.
    let count = 0;
    for (let step = 1e9; step >= 1; step /= 10) {
      while (price(composition[i], count + step) <= budget) count += step;
    }
    answer = Math.max(answer, count);
  }
  return answer;
}

