function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 100, k = 100;
    const budget = int(0, 1e8);
    const composition = Array.from({ length: k }, () => Array.from({ length: n }, () => int(1, 100)));
    const stock = Array.from({ length: n }, () => int(0, 1e8));
    const cost = Array.from({ length: n }, () => int(1, 100));
    return [n, k, budget, composition, stock, cost];
  }
  const n = int(1, 4), k = int(1, 4);
  const budget = rand() < 0.15 ? 0 : int(0, 80);
  const composition = Array.from({ length: k }, () => Array.from({ length: n }, () => int(1, 6)));
  const stock = Array.from({ length: n }, () => (rand() < 0.3 ? 0 : int(0, 25)));
  const cost = Array.from({ length: n }, () => int(1, 6));
  return [n, k, budget, composition, stock, cost];
}
